<script setup lang="ts">
import { computed,onMounted,reactive,ref } from "vue";import { Pige360SessionClient,type ApiProblem } from "@pige360/auth";type Row=Record<string,any>;const api=new Pige360SessionClient();const ready=ref(false),auth=ref(false),busy=ref(false),error=ref(""),notice=ref(""),email=ref(""),password=ref("");const ctx=ref<Row>({branding:{},requests:[],library_loans:[]});const form=reactive({request_type:"administrative",subject:"",description:"",priority:"normal",department:"Secretaria",sla_hours:72});const school=computed(()=>ctx.value.branding?.short_name||ctx.value.branding?.trade_name||ctx.value.branding?.legal_name||"Instituição");function msg(e:unknown){const p=(e as Error&{problem?:ApiProblem})?.problem;return p?.detail||(e instanceof Error?e.message:"Erro inesperado");}function apply(){document.documentElement.style.setProperty("--brand-primary",ctx.value.branding?.primary_color||"#006D77");document.documentElement.style.setProperty("--brand-secondary",ctx.value.branding?.secondary_color||"#0D1B2A");document.title=`${school.value} — Autoatendimento`;}
async function load(){ctx.value=await api.request<Row>("/portal/kiosk/me");const b=await api.request<Row>("/branding/current");ctx.value.branding=b.payload||b;apply();}async function boot(){try{await api.initialize();auth.value=!!api.tokens;if(auth.value)await load();}catch(e){error.value=msg(e);}finally{ready.value=true;}}async function login(){try{await api.login(email.value,password.value);auth.value=true;await load();}catch(e){error.value=msg(e);}}async function logout(){await api.logout();auth.value=false;}async function createRequest(){busy.value=true;try{await api.request("/service-requests",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(form)});notice.value="Protocolo criado.";Object.assign(form,{request_type:"administrative",subject:"",description:"",priority:"normal",department:"Secretaria",sla_hours:72});await load();}catch(e){error.value=msg(e);}finally{busy.value=false;}}onMounted(boot);
</script>
<template><div v-if="!ready" class="center">Inicializando autoatendimento…</div><div v-else-if="!auth" class="login-page"><form class="login-card" @submit.prevent="login"><div class="mark">◇</div><span class="eyebrow">Autoatendimento</span><h1>Identifique-se</h1><label>E-mail<input v-model="email" type="email" required></label><label>Senha<input v-model="password" type="password" required></label><p v-if="error" class="flash error">{{error}}</p><button class="primary">Continuar</button></form></div><div v-else class="mobile-shell"><header><div class="brand"><div class="mark">◇</div><div><strong>{{school}}</strong><small>Autoatendimento</small></div></div><button class="ghost" @click="logout">Encerrar</button></header><main><div v-if="notice" class="flash success">{{notice}}</div><div v-if="error" class="flash error">{{error}}</div><section class="welcome"><h1>Olá, {{ctx.person?.social_name||ctx.person?.full_name}}</h1><p>Consulte seus protocolos e serviços vinculados.</p></section><section class="grid two"><form class="panel form" @submit.prevent="createRequest"><h2>Novo protocolo</h2><label>Assunto<input v-model="form.subject" required></label><label>Descrição<textarea v-model="form.description" rows="5" required></textarea></label><button class="primary" :disabled="busy">Enviar solicitação</button></form><div class="panel"><h2>Empréstimos</h2><div class="list-row" v-for="l in ctx.library_loans" :key="l.id"><div><strong>{{l.title}}</strong><span>{{l.state}}</span></div><small>{{l.due_at||l.due_date}}</small></div><p v-if="!ctx.library_loans?.length" class="empty">Nenhum empréstimo ativo ou recente.</p></div></section><section class="panel"><div class="section-title"><h2>Meus protocolos</h2><span>{{ctx.requests?.length||0}}</span></div><div class="list-row" v-for="r in ctx.requests" :key="r.id"><div><strong>{{r.protocol}} · {{r.subject}}</strong><span>{{r.request_type}}</span></div><small>{{r.state}}</small></div><p v-if="!ctx.requests?.length" class="empty">Nenhum protocolo registrado.</p></section></main></div></template>
